&lt;li style=&quot;margin-top: 0; margin-bottom: 0; vertical-align: middle;&quot;&gt;&lt;span style=&quot;font-family: &#39;Times New Roman&#39;; font-size: 12.0pt;&quot;&gt;Monitor patient progress and adjust treatment plans as needed &lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;margin-top: 0; margin-bottom: 0; vertical-align: middle;&quot;&gt;&lt;span style=&quot;font-family: &#39;Times New Roman&#39;; font-size: 12.0pt;&quot;&gt;Support safe transitions of care and contribute to discharge planning &lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;margin-top: 0; margin-bottom: 0; vertical-align: middle;&quot;&gt;&lt;span style=&quot;font-family: &#39;Times New Roman&#39;; font-size: 12.0pt;&quot;&gt;Identify additional patient needs and collaborate with interdisciplinary teams &lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p style=&quot;margin: 0in; font-family: &#39;Times New Roman&#39;; font-size: 12.0pt;&quot;&gt;&lt;span style=&quot;font-weight: bold;&quot;&gt;Collaborate &amp;amp; Communicate&lt;/span&gt;&lt;/p&gt;
