&lt;li style=&quot;margin-top: 0px; margin-bottom: 0px; vertical-align: middle; font-family: &#39;times new roman&#39;, times, serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif; font-size: 12pt;&quot;&gt;Help maintain a clean, safe, and comfortable home environment&lt;/span&gt;&lt;/li&gt;
