&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Skills Immunoassay and biochemical assay&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:1,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:233,&amp;quot;335559991&amp;quot;:1071,&amp;quot;469777462&amp;quot;:[795],&amp;quot;469777927&amp;quot;:[0],&amp;quot;469777928&amp;quot;:[1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Laboratory experience with &lt;strong&gt;Western Blotting&lt;/strong&gt; and &lt;strong&gt;SDS-PAGE &lt;/strong&gt;is a &lt;span style=&quot;text-decoration: underline;&quot;&gt;must.&lt;/span&gt; Basic knowledge of immunoassays and fluorescence biochemistry is preferred. Hands on experience in protease assays in plate format with colorimetric or fluorometric detection is desired.&amp;nbsp; Ability to work with tissues for in vitro assays.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559737&amp;quot;:198,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
